def criar_filiacoes_existentes(apps, schema_editor):
    """Espelha os vínculos M2M já existentes na tabela ``filiacoes``.

    A tela de membros passa a usar a mesma relação para presença/agenda. O
    tenant de cada Filiacao é o tenant da própria Loja, nunca o do membro.
    """
    Membro = apps.get_model('contatos', 'Membro')
    Loja = apps.get_model('contatos', 'Loja')
    Filiacao = apps.get_model('contatos', 'Filiacao')
    through = Membro.lojas.through
    tenants_por_loja = dict(
        Loja.objects.values_list('pk', 'tenant_id'),
    )
    for membro_id, loja_id in through.objects.values_list(
        'membro_id', 'loja_id',
    ).iterator():
        tenant_id = tenants_por_loja.get(loja_id)
        if tenant_id is None:
            continue
        Filiacao.objects.update_or_create(
            membro_id=membro_id,
            loja_id=loja_id,
            defaults={'tenant_id': tenant_id},
        )


